select `j`.`jub_correlativo` AS `jub_correlativo`,`j`.`jub_dpi` AS `jub_dpi`,concat(`j`.`jub_nombres`,' ',`j`.`jub_apellidos`) AS `nombre_completo`,`j`.`jub_fecha_jubilacion` AS `jub_fecha_jubilacion`,`j`.`jub_estado` AS `jub_estado`,(select count(0) from `apps_rpjepq`.`rpj_prc_deuda_jubilado` where `apps_rpjepq`.`rpj_prc_deuda_jubilado`.`deu_id_jubilado` = `j`.`jub_correlativo`) AS `meses_total`,(select count(0) from `apps_rpjepq`.`rpj_prc_deuda_jubilado` where `apps_rpjepq`.`rpj_prc_deuda_jubilado`.`deu_id_jubilado` = `j`.`jub_correlativo` and `apps_rpjepq`.`rpj_prc_deuda_jubilado`.`deu_estado` = 'PAGADA') AS `meses_pagados`,(select count(0) from `apps_rpjepq`.`rpj_prc_deuda_jubilado` where `apps_rpjepq`.`rpj_prc_deuda_jubilado`.`deu_id_jubilado` = `j`.`jub_correlativo` and `apps_rpjepq`.`rpj_prc_deuda_jubilado`.`deu_estado` in ('PENDIENTE','PARCIAL')) AS `meses_pendientes`,(select ifnull(sum(`apps_rpjepq`.`rpj_prc_deuda_jubilado`.`deu_monto_pendiente`),0) from `apps_rpjepq`.`rpj_prc_deuda_jubilado` where `apps_rpjepq`.`rpj_prc_deuda_jubilado`.`deu_id_jubilado` = `j`.`jub_correlativo`) AS `deuda_pendiente`,(select ifnull(sum(`apps_rpjepq`.`rpj_prc_deuda_jubilado`.`deu_monto_pagado`),0) from `apps_rpjepq`.`rpj_prc_deuda_jubilado` where `apps_rpjepq`.`rpj_prc_deuda_jubilado`.`deu_id_jubilado` = `j`.`jub_correlativo`) AS `deuda_pagada` from `apps_rpjepq`.`rpj_mnt_jubilado` `j` where `j`.`jub_tipo_manejo` = 2 and `j`.`jub_estado` = 'ACTIVO'
